  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isPrimitive(value) {
  return value === null
    || typeof value === 'string'
    || typeof value === 'number'
    || typeof value === 'boolean';
}

function isNestedObject(value) {
  return isPlainObject(value);
}

function assertValidValue(value, key) {
  if (isPrimitive(value)) {
    return;
  }
  if (isNestedObject(value)) {
    for (const nestedKey of Object.keys(value)) {
      if (!isPrimitive(value[nestedKey])) {
        throw new TypeError(`invalid value for key "${key}"`);
      }
    }
    return;
  }
  throw new TypeError(`invalid value for key "${key}"`);
}

// Copy own enumerable string keys onto a fresh object, treating keys such as
// "__proto__" and "constructor" as ordinary data properties.
function copyOwnEnumerable(source) {
  const target = {};
  for (const key of Object.keys(source)) {
    Object.defineProperty(target, key, {
      value: source[key],
      writable: true,
      enumerable: true,
      configurable: true,
    });
  }
  return target;
}

export function mergeConfig(defaults, overrides = {}) {
  if (!isPlainObject(defaults) || !isPlainObject(overrides)) {
    throw new TypeError('expected configuration objects');
  }

  const result = {};

  for (const key of Object.keys(defaults)) {
    const value = defaults[key];
    assertValidValue(value, key);
    if (isNestedObject(value)) {
      Object.defineProperty(result, key, {
        value: copyOwnEnumerable(value),
        writable: true,
        enumerable: true,
        configurable: true,
      });
    } else {
      Object.defineProperty(result, key, {
        value,
        writable: true,
        enumerable: true,
        configurable: true,
      });
    }
  }

  for (const key of Object.keys(overrides)) {
    const value = overrides[key];
    assertValidValue(value, key);
    const existing = Object.prototype.hasOwnProperty.call(result, key)
      ? result[key]
      : undefined;

    if (isNestedObject(value) && isNestedObject(existing)) {
      const merged = copyOwnEnumerable(existing);
      for (const nestedKey of Object.keys(value)) {
        Object.defineProperty(merged, nestedKey, {
          value: value[nestedKey],
          writable: true,
          enumerable: true,
          configurable: true,
        });
      }
      Object.defineProperty(result, key, {
        value: merged,
        writable: true,
        enumerable: true,
        configurable: true,
      });
    } else if (isNestedObject(value)) {
      Object.defineProperty(result, key, {
        value: copyOwnEnumerable(value),
        writable: true,
        enumerable: true,
        configurable: true,
      });
    } else {
      Object.defineProperty(result, key, {
        value,
        writable: true,
        enumerable: true,
        configurable: true,
      });
    }
  }

  return result;
}
