{"path": "/tmp/check.mjs", "content": "import assert from 'node:assert/strict';
import { mergeConfig } from '/workspace/config.mjs';

// public tests
assert.deepEqual(mergeConfig({ mode: 'safe', retries: 3 }, { mode: 'fast' }), { mode: 'fast', retries: 3 });
assert.deepEqual(mergeConfig({ network: { host: 'localhost', port: 80 } }, { network: { port: 443 } }), { network: { host: 'localhost', port: 443 } });
assert.deepEqual(mergeConfig({ enabled: true, retries: 3 }, { enabled: false, retries: 0 }), { enabled: false, retries: 0 });

// TypeError for bad args
for (const bad of [null, undefined, [], 1, 'x', true]) {
  assert.throws(() => mergeConfig(bad, {}), TypeError);
  assert.throws(() => mergeConfig({}, bad), TypeError);
}
assert.throws(() => mergeConfig(), TypeError);

// inherited keys ignored
const proto = { inherited: 'nope' };
const d = Object.create(proto); d.own = 1;
const o = Object.create(proto); o.own2 = 2;
assert.deepEqual(mergeConfig(d, o), { own: 1, own2: 2 });

// __proto__ and constructor as ordinary keys from JSON.parse
const dj = JSON.parse('{"__proto__": {"a": 1}, "constructor": "c"}');
const oj = JSON.parse('{"__proto__": {"b": 2}}');
const r = mergeConfig(dj, oj);
assert.deepEqual(Object.keys(r).sort(), ['__proto__', 'constructor']);
assert.deepEqual(r['__proto__'], { a: 1, b: 2 });
assert.equal(r.constructor, 'c');
assert.equal(Object.getPrototypeOf(r), Object.prototype);

// no mutation / no retained references
const defaults = { net: { host: 'h', port: 1 }, x: 1 };
const overrides = { net: { port: 2 } };
const out = mergeConfig(defaults, overrides);
assert.deepEqual(defaults, { net: { host: 'h', port: 1 }, x: 1 });
assert.deepEqual(overrides, { net: { port: 2 } });
assert.notEqual(out.net, defaults.net);
assert.notEqual(out.net, overrides.net);

// independence across repeated calls
const a = mergeConfig(defaults, overrides);
const b = mergeConfig(defaults, overrides);
assert.notEqual(a, b);
assert.notEqual(a.net, b.net);
a.net.host = 'changed';
assert.equal(b.net.host, 'h');
assert.equal(defaults.net.host, 'h');

// nested override replaces when default not object
assert.deepEqual(mergeConfig({ k: 1 }, { k: { a: 1 } }), { k: { a: 1 } });
// nested default replaced by primitive override
assert.deepEqual(mergeConfig({ k: { a: 1 } }, { k: null }), { k: null });
assert.deepEqual(mergeConfig({ k: { a: 1 } }, { k: false }), { k: false });
assert.deepEqual(mergeConfig({ k: { a: 1 } }, { k: 0 }), { k: 0 });

// invalid nested value throws
assert.throws(() => mergeConfig({ k: { a: {} } }, {}), TypeError);
assert.throws(() => mergeConfig({}, { k: { a: [] } }), TypeError);
assert.throws(() => mergeConfig({ k: [1] }, {}), TypeError);

// null prototype objects accepted
const np = Object.create(null); np.a = 1;
assert.deepEqual(mergeConfig(np, {}), { a: 1 });

console.log('all checks passed');
"}

